<?php

namespace App\Modules\Infrastructure\Auth\Http;

use App\Core\Registration\RegistrationFunnelEvent;
use Illuminate\Database\UniqueConstraintViolationException;
use Illuminate\Http\JsonResponse;
use Illuminate\Http\Request;
use Illuminate\Routing\Controller;

/**
 * Public registration funnel — POST /api/register/funnel-track (unauthenticated, throttled 30/min).
 *
 * ADR-849 (Leezr 4.2 M10) : a step really passed on the public registration screen, keyed by a random journey id
 * generated by the browser (no personal data). Idempotent : one row per (journey, step) — a resent step answers
 * `duplicate`. Only the traffic origin (host of the referrer, ≤ 100 chars) is kept : no name, e-mail, password,
 * token or free field is accepted. `completed` is never accepted here (written by the server at registration).
 */
class FunnelTrackController extends Controller
{
    public function __invoke(Request $request): JsonResponse
    {
        $data = $request->validate([
            'funnel_id' => 'required|uuid',
            'step' => 'required|string|in:'.implode(',', RegistrationFunnelEvent::CLIENT_STEPS),
            'source' => 'nullable|string|max:100',
        ]);

        try {
            $event = RegistrationFunnelEvent::firstOrCreate(
                ['funnel_id' => $data['funnel_id'], 'step' => $data['step']],
                ['session_id' => $data['funnel_id'], 'metadata' => $data['step'] === 'started' && ! empty($data['source'])
                    ? ['source' => self::host($data['source'])] : null],
            );
        } catch (UniqueConstraintViolationException) {
            return response()->json(['ok' => true, 'duplicate' => true]); // concurrent identical request
        }

        return response()->json(['ok' => true, 'duplicate' => ! $event->wasRecentlyCreated]);
    }

    /** referrer reduced to its host (never a path or a query string, which may carry personal data) */
    private static function host(string $source): ?string
    {
        if ($source === 'direct') {
            return 'direct';
        }
        $host = parse_url($source, PHP_URL_HOST) ?: (preg_match('/^[a-z0-9.-]+$/i', $source) ? $source : null);

        return $host ? mb_substr(strtolower($host), 0, 100) : null;
    }
}
